import math
import re
from fractions import Fraction

_UNITS = {
    "s": 1, "sec": 1, "secs": 1, "second": 1, "seconds": 1,
    "m": 60, "min": 60, "mins": 60, "minute": 60, "minutes": 60,
    "h": 3600, "hr": 3600, "hrs": 3600, "hour": 3600, "hours": 3600,
    "d": 86400, "day": 86400, "days": 86400,
    "w": 604800, "wk": 604800, "wks": 604800, "week": 604800, "weeks": 604800,
}

_NUM = r"(?:\d+(?:\.\d*)?|\.\d+)"
_COMPONENT = re.compile(r"\s*(" + _NUM + r")\s*([A-Za-z]+)")
_ISO = re.compile(
    r"P(?:(" + _NUM + r")W)?(?:(" + _NUM + r")D)?"
    r"(?:T(?:(" + _NUM + r")H)?(?:(" + _NUM + r")M)?(?:(" + _NUM + r")S)?)?"
)
_INT = re.compile(r"\d+")
_CLOCK_FIELD = re.compile(r"\d+(?:\.\d+)?")


def _round_half_up(value: Fraction) -> int:
    return math.floor(value + Fraction(1, 2))


def _to_fraction(s: str) -> Fraction:
    return Fraction(s)


def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""
    if not isinstance(text, str):
        raise ValueError("duration must be a string")
    s = text.strip()
    if not s:
        raise ValueError("empty duration")

    # Bare non-negative integer: seconds.
    if _INT.fullmatch(s):
        return int(s)

    # ISO 8601 duration.
    if s.startswith("P"):
        if s.endswith("T"):
            raise ValueError(f"invalid ISO duration: {text!r}")
        m = _ISO.fullmatch(s)
        if not m or not any(m.groups()):
            raise ValueError(f"invalid ISO duration: {text!r}")
        weeks, days, hours, minutes, seconds = m.groups()
        total = Fraction(0)
        for val, mult in (
            (weeks, 604800),
            (days, 86400),
            (hours, 3600),
            (minutes, 60),
            (seconds, 1),
        ):
            if val is not None:
                total += _to_fraction(val) * mult
        return _round_half_up(total)

    # Clock notation: hh:mm:ss or mm:ss.
    if ":" in s:
        fields = s.split(":")
        if len(fields) not in (2, 3):
            raise ValueError(f"invalid clock duration: {text!r}")
        if not all(_CLOCK_FIELD.fullmatch(f) for f in fields[:-1]):
            raise ValueError(f"invalid clock duration: {text!r}")
        if not _CLOCK_FIELD.fullmatch(fields[-1]):
            raise ValueError(f"invalid clock duration: {text!r}")
        nums = [_to_fraction(f) for f in fields]
        # Minutes and seconds fields must be below 60.
        for f in nums[1:]:
            if f >= 60:
                raise ValueError(f"invalid clock duration: {text!r}")
        if len(nums) == 2:
            total = nums[0] * 60 + nums[1]
        else:
            total = nums[0] * 3600 + nums[1] * 60 + nums[2]
        return _round_half_up(total)

    # Number+unit components, optionally separated by spaces.
    pos = 0
    total = Fraction(0)
    while pos < len(s):
        m = _COMPONENT.match(s, pos)
        if not m:
            raise ValueError(f"invalid duration: {text!r}")
        num, unit = m.group(1), m.group(2).lower()
        if unit not in _UNITS:
            raise ValueError(f"unknown unit in duration: {text!r}")
        total += _to_fraction(num) * _UNITS[unit]
        pos = m.end()
        # Allow trailing whitespace only.
        rest = s[pos:]
        if rest and not rest.strip():
            break
    return _round_half_up(total)

